window.addEventListener('error',e=>{
  if(document.getElementById('__fatalErrorBanner'))return;
  let msg=e.error?e.error.message:e.message;
  if(!msg || (msg==='Script error.' && !e.filename))return;
  let b=document.createElement('div');
  b.id='__fatalErrorBanner';
  b.style.cssText='position:fixed;top:0;left:0;right:0;z-index:99999;background:#c0392b;color:#fff;padding:14px 16px;font:13px/1.4 -apple-system,sans-serif;white-space:pre-wrap';
  b.textContent='Es ist ein Fehler aufgetreten – bitte diesen Text an den App-Ersteller schicken:\n'+msg+'\n(Zeile '+e.lineno+', '+ (e.filename||'').split('/').pop()+')';
  document.body?document.body.prepend(b):window.addEventListener('DOMContentLoaded',()=>document.body.prepend(b));
});
