const QTY_WHOLE_MAX=20;
const QTY_FRACS=[{v:0,l:'\u2013'},{v:0.125,l:'\u215b'},{v:0.25,l:'\u00bc'},{v:1/3,l:'\u2153'},{v:0.5,l:'\u00bd'},{v:2/3,l:'\u2154'},{v:0.75,l:'\u00be'},{v:0.875,l:'\u215e'}];
function qtyToParts(qty){qty=+qty||0;let whole=Math.floor(qty+1e-6);let frac=qty-whole;let best=QTY_FRACS[0],bestDiff=Infinity;QTY_FRACS.forEach(fr=>{let d=Math.abs(fr.v-frac);if(d<bestDiff){bestDiff=d;best=fr}});return{whole,frac:best.v}}
function formatQty(qty){let p=qtyToParts(qty),whole=p.whole,frac=p.frac;let fl=(QTY_FRACS.find(f=>Math.abs(f.v-frac)<1e-6)||QTY_FRACS[0]).l;if(whole===0&&frac===0)return '0';if(frac===0)return String(whole);if(whole===0)return fl;return whole+' '+fl}
function gramsForQty(food,qty){if(food==null||food.grams==null)return null;return Math.round(food.grams*qty)}
function buildWheelHTML(id,items,selIndex){let itemsHtml=items.map((it,i)=>`<div class="qty-wheel-item${i===selIndex?' active':''}" data-index="${i}">${it.l}</div>`).join('');return `<div class="qty-wheel" id="${id}"><div class="qty-wheel-track"><div class="qty-wheel-pad"></div>${itemsHtml}<div class="qty-wheel-pad"></div></div></div>`}
function attachWheel(el,items,initialIndex,onChange){
  const ITEM_H=36;
  function itemsEls(){return Array.from(el.querySelectorAll('.qty-wheel-item'))}
  function setActive(idx){itemsEls().forEach((it,i)=>it.classList.toggle('active',i===idx))}
  el.scrollTop=initialIndex*ITEM_H;
  setActive(initialIndex);
  let currentIndex=initialIndex;
  let timer=null;
  el.addEventListener('scroll',()=>{
    if(timer)clearTimeout(timer);
    timer=setTimeout(()=>{
      let idx=Math.max(0,Math.min(items.length-1,Math.round(el.scrollTop/ITEM_H)));
      if(idx!==currentIndex){currentIndex=idx;onChange(items[idx].v)}
      setActive(idx);
      el.scrollTo({top:idx*ITEM_H,behavior:'smooth'});
    },90);
  });
  itemsEls().forEach((it,i)=>it.onclick=()=>{el.scrollTo({top:i*ITEM_H,behavior:'smooth'})});
  return{get:()=>items[currentIndex].v,set:(idx)=>{currentIndex=idx;setActive(idx);el.scrollTop=idx*ITEM_H}};
}
function openQuantitySheet(food,initialQty,onConfirm){
  let wholeItems=[];for(let i=0;i<=QTY_WHOLE_MAX;i++)wholeItems.push({v:i,l:i===0?'\u2013':String(i)});
  let parts=qtyToParts(initialQty),whole=parts.whole,frac=parts.frac;
  let wholeIdx=wholeItems.findIndex(x=>x.v===whole);if(wholeIdx<0)wholeIdx=1;
  let fracIdx=QTY_FRACS.findIndex(x=>Math.abs(x.v-frac)<1e-6);if(fracIdx<0)fracIdx=0;
  openSheet('Menge ausw\u00e4hlen',`
<p style="margin:0 0 10px;font-weight:650">${escapeHtml(food.name)}</p>
<div class="qty-picker">
${buildWheelHTML('qtyWholeWheel',wholeItems,wholeIdx)}
${buildWheelHTML('qtyFracWheel',QTY_FRACS,fracIdx)}
<div class="qty-selection-line"></div>
</div>
<p class="qty-grams-display" id="qtyGramsLine"></p>
<button class="primary" id="qtyConfirm">\u00dcbernehmen</button>`);
  let wholeCtl=attachWheel($('#qtyWholeWheel'),wholeItems,wholeIdx,update2);
  let fracCtl=attachWheel($('#qtyFracWheel'),QTY_FRACS,fracIdx,update2);
  function currentQty(){return(wholeCtl.get()||0)+(fracCtl.get()||0)}
  function update2(){
    let q=currentQty();
    let g=gramsForQty(food,q);
    $('#qtyGramsLine').textContent=g!=null?('Menge: '+g+' g'):'';
  }
  update2();
  $('#qtyConfirm').onclick=()=>{let q=currentQty();if(q<=0)q=1;closeSheet();onConfirm(q)};
}
