          let nf={id:'custom-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),name:ing.name,meal,kcal:ing.kcal,p:ing.p,c:ing.c,f:ing.f,fiber:ing.fiber,sugar:ing.sugar,sat:ing.sat,salt:ing.salt,sodium:0,chol:0,cats:[{cat:'extras',amt:1}]};
